import { initDatabase } from './db.js';
import { addFactTags, removeFactTags, setFactTags, listTags, findFactsByTags, getFactTags, } from './fact-db.js';
const args = process.argv.slice(2);
const BROWSE = args.includes('--browse');
if (args.includes('--help') || args.includes('-h') || (args.length === 0 && !BROWSE)) {
    console.log(`
Usage: memory-bank tag <fact-id> [tags...] [options]
       memory-bank tags [options]

Tags are the one labelling axis you control directly. The ontology
(domain/category) is generated by the LLM and is not addressable by hand;
tags survive re-classification, re-embedding, and consolidation because the
automatic pipeline never writes them.

TAG A FACT
  memory-bank tag <fact-id> verified reviewed   Add tags
  memory-bank tag <fact-id> --remove draft      Remove tags
  memory-bank tag <fact-id> --set a b           Replace all tags
  memory-bank tag <fact-id> --clear             Remove every tag
  memory-bank tag <fact-id>                     Show current tags

BROWSE
  memory-bank tags                              Tag index (tag -> count)
  memory-bank tags --project <path>             Scope the index to a project
  memory-bank tags --find mobile billing        Facts carrying ALL these tags
  memory-bank tags --find mobile --any          Facts carrying ANY of them
  memory-bank tags --find verified --limit 100

NOTES
  - Tags are normalized: trimmed, inner spaces become '-', lowercased.
    "Needs Check" and "needs-check" are the same tag.
  - Allowed characters: letters (Korean included), digits, - _ . / :
  - Max 64 chars per tag, 32 tags per fact.
  - Get fact ids from: memory-bank search, or the MCP search_facts tool.
`);
    process.exit(0);
}
function flagValue(name) {
    const i = args.indexOf(name);
    return i >= 0 ? args[i + 1] : undefined;
}
function positionals(stopFlags) {
    const out = [];
    for (let i = 0; i < args.length; i++) {
        const a = args[i];
        if (a.startsWith('--')) {
            if (stopFlags.includes(a))
                i++; // skip this flag's value
            continue;
        }
        out.push(a);
    }
    return out;
}
const VALUE_FLAGS = ['--project', '--limit'];
const db = initDatabase();
try {
    // ── browse mode: memory-bank tags ...
    if (BROWSE) {
        const project = flagValue('--project') || process.cwd();
        const findIdx = args.indexOf('--find');
        if (findIdx >= 0) {
            const wanted = [];
            for (let i = findIdx + 1; i < args.length; i++) {
                if (args[i].startsWith('--'))
                    break;
                wanted.push(args[i]);
            }
            if (!wanted.length) {
                console.error('--find needs at least one tag');
                process.exit(1);
            }
            const limitRaw = flagValue('--limit');
            const facts = findFactsByTags(db, wanted, {
                project,
                match: args.includes('--any') ? 'any' : 'all',
                limit: limitRaw ? Number(limitRaw) : 50,
            });
            const joiner = args.includes('--any') ? ' OR ' : ' AND ';
            console.log(`Facts tagged ${wanted.join(joiner)} — ${facts.length} result(s)\n`);
            for (const f of facts) {
                console.log(`[${f.category}] ${f.fact}`);
                console.log(`  id:    ${f.id}`);
                console.log(`  tags:  ${(f.tags ?? []).join(', ')}`);
                console.log(`  scope: ${f.scope_type}${f.scope_project ? ` (${f.scope_project})` : ''}\n`);
            }
        }
        else {
            const index = listTags(db, { project });
            if (!index.length) {
                console.log('No tags yet.\n');
                console.log('Tags are user-assigned — the extraction pipeline never creates them.');
                console.log('Start with:  memory-bank tag <fact-id> <your-label>');
            }
            else {
                console.log(`${index.length} distinct tag(s) — project: ${project}\n`);
                const width = Math.max(...index.map(t => t.tag.length));
                for (const { tag, count } of index) {
                    console.log(`  ${tag.padEnd(width)}  ${count}`);
                }
            }
        }
    }
    else {
        // ── write mode: memory-bank tag <fact-id> ...
        const factId = args[0];
        if (!factId || factId.startsWith('--')) {
            console.error('Usage: memory-bank tag <fact-id> [tags...]');
            process.exit(1);
        }
        if (args.includes('--clear')) {
            setFactTags(db, factId, []);
            console.log(`Cleared all tags on ${factId}`);
        }
        else if (args.includes('--set')) {
            const i = args.indexOf('--set');
            const next = args.slice(i + 1).filter(a => !a.startsWith('--'));
            const tags = setFactTags(db, factId, next);
            console.log(`Tags on ${factId}: ${tags.length ? tags.join(', ') : '(none)'}`);
        }
        else if (args.includes('--remove')) {
            const i = args.indexOf('--remove');
            const drop = args.slice(i + 1).filter(a => !a.startsWith('--'));
            const r = removeFactTags(db, factId, drop);
            if (r.removed.length)
                console.log(`Removed: ${r.removed.join(', ')}`);
            if (r.absent.length)
                console.log(`Not present: ${r.absent.join(', ')}`);
            console.log(`Tags on ${factId}: ${r.tags.length ? r.tags.join(', ') : '(none)'}`);
        }
        else {
            const add = positionals(VALUE_FLAGS).slice(1);
            if (!add.length) {
                const tags = getFactTags(db, factId);
                console.log(`Tags on ${factId}: ${tags.length ? tags.join(', ') : '(none)'}`);
            }
            else {
                const r = addFactTags(db, factId, add);
                console.log(r.added.length ? `Added: ${r.added.join(', ')}` : 'Added: (already present)');
                console.log(`Tags on ${factId}: ${r.tags.join(', ')}`);
            }
        }
    }
}
catch (error) {
    console.error(`Error: ${error instanceof Error ? error.message : String(error)}`);
    process.exitCode = 1;
}
finally {
    db.close();
}
